import math

def check_candidate(n):
    # Check if 2n - 1 is zero (only happens if n=1/2, which is not an integer)
    divisor = 2 * n - 1
    if divisor == 0:
        return False

    try:
        # Calculate (n+2)! + 1
        factorial_plus_one = math.factorial(n + 2) + 1

        # Calculate the numerator: 3 * ((n+2)! + 1)
        numerator = 3 * factorial_plus_one

        # Check divisibility
        if numerator % divisor == 0:
            return True
        else:
            return False
    except OverflowError:
        # For very large n, factorial might overflow standard integer types
        return None # Or handle as necessary, but we are testing small n
    except ValueError:
        # For n < 0, but we are constrained to nonnegative integers
        return False

test_range = range(0, 13) # Test n from 0 to 12
solutions_found = []
for n in test_range:
    if check_candidate(n):
        solutions_found.append(n)

print(f"Solutions for 0 <= n <= 12 are: {solutions_found}")
